#include <stddef.h>

/* Index of first match, or -1 */
int linear_search(const int a[], int n, int target) {
    for (int i = 0; i < n; i++)
        if (a[i] == target) return i;
    return -1;
}

/* Fill out[] with all matching indexes, return how many */
int find_all(const int a[], int n, int target, int out[]) {
    int count = 0;
    for (int i = 0; i < n; i++)
        if (a[i] == target) out[count++] = i;
    return count;
}

struct node { int v; struct node *next; };

/* Same idea on a singly linked list: return the node or NULL */
struct node *list_search(struct node *head, int target) {
    for (struct node *p = head; p; p = p->next)
        if (p->v == target) return p;
    return NULL;
}

int sentinel_search(int a[], int n, int target) {
    if (n == 0) return -1;
    int last = a[n - 1];
    a[n - 1] = target;                   /* guarantee termination */
    int i = 0;
    while (a[i] != target) i++;
    a[n - 1] = last;                     /* restore */
    return (i < n - 1 || last == target) ? i : -1;
}

typedef int (*pred_fn)(const void *elem, void *ctx);

/* Returns pointer to first element for which pred is nonzero, else NULL */
void *find_if(const void *base, size_t n, size_t size, pred_fn pred, void *ctx) {
    const char *p = base;
    for (size_t i = 0; i < n; i++, p += size)
        if (pred(p, ctx)) return (void *)p;
    return NULL;
}
